function login(message='',register=false){setMenu(false);allowed=false;root.innerHTML=`<div class="login"><section class="login-side"><img src="assets/logo.png" alt="أكس سبيس"><span class="tag">لوحة الإدارة</span><h1>كل عمليات أكس سبيس<br>بمكان واحد.</h1><p>تابع الطلبات، حدّث المنتجات، وراجع حسابات التجار والدعم.</p><div class="actions">${icon('shield')}<span>دخول خاص بالإدارة</span></div></section><section class="login-main"><form class="login-form" id="login-form"><div class="brand"><img src="assets/logo.png" alt="أكس سبيس"></div><h2>${register?'إنشاء حساب للإدارة':'تسجيل دخول الإدارة'}</h2><p>استخدم حساب الإدارة المصرّح له.</p>${field('identity','البريد الإلكتروني أو رقم الهاتف','','text','required autocomplete="username" dir="ltr"') }<div class="field"><label for="password">كلمة السر</label><div class="password"><input id="password" name="password" type="password" required autocomplete="current-password" dir="ltr"><button type="button" data-action="show-password">إظهار</button></div></div><div id="login-error" class="inline-error" role="alert">${esc(message)}</div><button class="primary" type="submit">${register?'إنشاء الحساب':'تسجيل الدخول'}</button><button class="guest-preview" type="button" data-action="${register?'login-mode':'register-mode'}">${register?'عندي حساب — تسجيل الدخول':'إنشاء حساب للإدارة'}</button><button class="guest-preview" type="button" data-action="preview">معاينة الداشبورد</button><div class="login-note">المعاينة تعرض الواجهة فقط. بيانات التجار والحسابات متاحة لحسابات الإدارة المصرّح لها.</div></form></section></div>`;$('#login-form').onsubmit=async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button[type=submit]');b.disabled=true;let f=new FormData(e.currentTarget),identity=f.get('identity').trim().replace(/[٠-٩]/g,c=>'0123456789'['٠١٢٣٤٥٦٧٨٩'.indexOf(c)]);try{if(!identity.includes('@')){if(!/^07\d{9}$/.test(identity))throw new Error('الرقم لازم 11 رقم ويبدأ بـ07');identity+='@gmail.com'}if(register){if(String(f.get('password')).length<8)throw new Error('كلمة السر لازم 8 أحرف على الأقل');await result(sb.auth.signUp({email:identity,password:f.get('password'),options:{data:{adminRequested:true}}}));await sb.auth.signOut();user=null;login('تم إنشاء الحساب. أرسل بريده لمالك المشروع حتى يفعّل صلاحية الإدارة.')}else{await result(sb.auth.signInWithPassword({email:identity,password:f.get('password')}));await start()}}catch(e){const target=$('#login-error');if(target)target.textContent=errorText(e)}finally{b.disabled=false}}}
async function withDeadline(p){let timer;try{return await Promise.race([p,new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error('الاتصال تأخر. حاول تسجيل الدخول مرة ثانية.')),15000)})])}finally{clearTimeout(timer)}}
async function start(){preview=false;try{const session=await withDeadline(result(sb.auth.getSession()));user=session?.session?.user;if(!user)return login();allowed=await result(sb.rpc('x_admin_access'));if(!allowed){await sb.auth.signOut();user=null;return login('هذا الحساب غير مخوّل للإدارة. اطلب من مالك المشروع تفعيل صلاحية الإدارة لحسابك.')}render();subscribe();await refresh()}catch(e){allowed=false;login('تعذر الاتصال: '+errorText(e))}}

async function allRows(t){let out=[],offset=0;for(;;){let query=sb.from(t).select('*').order(t==='x_settings'?'id':t==='x_referrals'?'referred_id':t==='x_profiles'?'user_id':'id');const r=await result(query.range(offset,offset+499));out.push(...r);if(r.length<500)return out;offset+=500}}
const changedTables=new Set();
let refreshFlight=null;
async function refresh(tables=null){
 if(preview){render();return}if(!allowed)return;
 if(refreshFlight)return refreshFlight;
 const owner=user?.id,epoch=requestEpoch;
 refreshFlight=(async()=>{try{
  const selected=tables||Object.keys(names);
  const entries=await Promise.all(selected.filter(t=>t in names).map(async t=>[t,await allRows(t)]));
  if(owner!==user?.id||epoch!==requestEpoch||!allowed)return;
  data={...data,...Object.fromEntries(entries)};lastSync=new Date();
  const scroll=window.scrollY,focus=document.activeElement;
  const focusId=focus?.id,pos=focus?.selectionStart;
  if(!productPage)render();window.scrollTo(0,scroll);
  if(focusId){const next=document.getElementById(focusId);next?.focus({preventScroll:true});if(pos!=null&&next?.setSelectionRange)next.setSelectionRange(pos,pos)}
  if(activeTicket&&dialog.open)await refreshChat(activeTicket);
 }catch(e){toast('تعذر تحديث البيانات: '+errorText(e));}finally{refreshFlight=null;}})();
 return refreshFlight;
}
function scheduleChange(table){
 changedTables.add(table);if(timer)return;
 timer=setTimeout(async()=>{timer=null;const tables=[...changedTables];changedTables.clear();await refresh(tables)},120);
}
function subscribe(){
 if(channel)sb.removeChannel(channel);
 channel=sb.channel('xspace-dashboard-'+user.id).on('postgres_changes',{event:'*',schema:'public'},payload=>{
  if(payload.table==='x_orders'&&payload.eventType==='INSERT'){
   const order=payload.new;
   toast('وصل طلب جديد رقم '+(order.order_number||order.id));
   scheduleChange('x_orders');
  }else if(payload.table==='x_messages'){
   const r=payload.new||payload.old,t=data.x_tickets?.find(t=>t.id===r.ticket_id);
   if(t){t.latest_at=r.created_at||new Date().toISOString();}
   scheduleChange('x_messages');
  }else scheduleChange(payload.table);
 }).subscribe(status=>{if(status==='SUBSCRIBED'&&lastSync)refresh()});
}
