function render(){if(productPage){dialog.append($('#dialog-content'));productPage=false;root.classList.remove('product-page')}setMenu(false);const sec=sections.find(s=>s[0]===route)||sections[0];root.innerHTML=`<div class="shell"><button class="sidebar-backdrop" data-action="menu-close" aria-label="إغلاق القائمة" hidden></button><aside class="sidebar" id="sidebar"><div><div class="brand"><img src="assets/logo.png" alt="أكس سبيس"></div><small>لوحة الإدارة</small></div><nav class="nav" aria-label="أقسام الإدارة">${sections.map(s=>`<button data-route="${s[0]}" class="${route===s[0]?'active':''}" ${route===s[0]?'aria-current="page"':''}>${icon(s[2])}${s[1]}</button>`).join('')}</nav><div class="bottom"><small>${preview?'وضع المعاينة':esc(user?.email||'الإدارة')}</small>${button('تسجيل الخروج','logout')}</div></aside><main class="workspace"><header class="topbar"><div class="actions">${button('☰','menu','','mobile-menu')}<div><h1>${sec[1]}</h1><p>${lastSync?'آخر تحديث '+lastSync.toLocaleTimeString('ar-IQ-u-nu-latn'):'أكس سبيس'}</p></div></div><div class="actions">${button('تحديث','refresh') }<div class="avatar">X</div></div></header>${preview?'<div class="previewbar">معاينة الواجهة · البيانات المعروضة فارغة، والتغييرات تتطلب حساب إدارة.</div>':''}<div id="page"></div></main></div>`;page();setMenu(false);}
function page(){const p=$('#page');if(!p)return;viewEpoch++;if(route==='home')p.innerHTML=home();else if(route==='orders')p.innerHTML=orders();else if(route==='products')p.innerHTML=products();else if(route==='categories')p.innerHTML=categories();else if(route==='merchants')p.innerHTML=merchants();else if(route==='finance')p.innerHTML=finance();else if(route==='support')p.innerHTML=support();else if(route==='exchange')p.innerHTML=exchange();else if(route==='notifications')p.innerHTML=notifications();else if(route==='settings')p.innerHTML=settings();else if(route==='audit')p.innerHTML=audit();wirePage()}
function home(){const os=rows('x_orders'),pending=rows('x_withdrawals').filter(r=>r.status==='قيد الانتظار'),delivered=os.filter(r=>r.status==='تم التوصيل'),active=os.filter(r=>!['تم التوصيل','مرفوض'].includes(r.status));return `<div class="metrics">${metric('الطلبات النشطة',active.length,'orders')}${metric('الطلبات المسلّمة',delivered.length,'products')}${metric('التجار',rows('x_profiles').length,'users')}${metric('سحوبات تنتظر المراجعة',money(pending.reduce((n,r)=>n+r.amount,0)),'wallet',pending.length+' طلب')}</div><div class="grid"><section class="panel"><div class="panelhead"><h2>آخر الطلبات</h2><button data-route="orders">عرض الطلبات</button></div>${orderTable(os.toSorted(newest).slice(0,6))}</section><section class="panel"><h2>حالات الطلبات</h2>${os.length?statuses.map(s=>{const n=os.filter(r=>r.status===s).length;return `<div class="barline"><div class="barlabel"><span>${s}</span><strong>${n}</strong></div><div class="track"><div class="fill" style="width:${n/os.length*100}%"></div></div></div>`}).join(''):empty('بانتظار أول طلب','تظهر إحصائيات الحالات بعد وصول الطلبات.')}</section></div><div class="grid"><section class="panel"><div class="panelhead"><h2>تحتاج مراجعتك</h2><button data-route="merchants">مراجعة التجار</button></div><div class="detailgrid"><div><span>طلبات إلغاء</span><strong>${os.filter(r=>r.cancellation_requested).length}</strong></div><div><span>تعديل بيانات التجار</span><strong>${rows('x_profile_requests').filter(r=>r.status==='pending').length}</strong></div><div><span>محادثات مفتوحة</span><strong>${rows('x_tickets').filter(r=>r.status==='open').length}</strong></div><div><span>منتجات مخزونها منخفض</span><strong>${rows('x_products').filter(r=>r.active&&r.stock<5).length}</strong></div></div></section><section class="panel"><h2>أرباح التجار المسلّمة</h2><div class="account-total">${money(delivered.reduce((n,r)=>n+(Number(r.payload?.profit)||0),0))}</div><p class="muted">مجموع أرباح التجار من الطلبات المسلّمة، قبل السحوبات.</p></section></div>`}
function toolbar(label,select=''){return `<div class="toolbar"><input id="search" aria-label="${label}" placeholder="${label}" value="${esc(search)}">${select}</div>`}
function matches(r){return !search||JSON.stringify(r).toLowerCase().includes(search.toLowerCase())||merchantName(r.merchant_id).includes(search)}
function orderTable(list){return table(['الطلب','الزبون / التاجر','المحافظة','الإجمالي','الحالة',''],list.map(o=>tr([`<strong class="code">${esc(o.id.slice(0,12))}</strong><span class="sub">${date(o.created_at)}</span>`,`${esc(o.payload?.customer?.name)}<span class="sub">${esc(merchantName(o.merchant_id))}</span>`,esc(o.payload?.customer?.province),money((o.payload?.sales||0)+(o.payload?.delivery||0)),badge(o.status)+(o.cancellation_requested?'<span class="sub">طلب إلغاء</span>':''),button('التفاصيل','order',o.id)])))}
function orders(){let list=rows('x_orders').filter(matches).filter(o=>!filter||filter==='cancel'?(!filter||o.cancellation_requested):o.status===filter).toSorted(newest);return `<div class="chips">${['',...statuses,'cancel'].map(s=>`<button data-filter="${s}" class="${filter===s?'active':''}">${s==='cancel'?'طلبات الإلغاء':s||'كل الطلبات'} <span class="muted">${rows('x_orders').filter(o=>!s||s==='cancel'?(!s||o.cancellation_requested):o.status===s).length}</span></button>`).join('')}</div>${toolbar('ابحث برقم الطلب، الزبون أو التاجر')}<section class="panel">${orderTable(list)}</section>`}
function products(){let list=rows('x_products').filter(matches).filter(p=>!filter||filter==='inactive'?!filter||!p.active:filter==='low'?p.stock<5:p.active).toSorted(newest);return `<div class="panelhead"><span class="muted">${rows('x_products').length} منتج</span>${button('+ إضافة منتج','product-new','','primary')}</div>${toolbar('ابحث باسم المنتج أو رقمه',`<select id="filter" aria-label="فلترة المنتجات"><option value="">كل المنتجات</option><option value="active" ${filter==='active'?'selected':''}>المفعّلة</option><option value="inactive" ${filter==='inactive'?'selected':''}>المخفية</option><option value="low" ${filter==='low'?'selected':''}>مخزون أقل من 5</option></select>`)}<div class="product-grid">${list.map(p=>`<article class="product"><div class="product-image">${p.data.image&&safeUrl(p.data.image)?`<img src="${esc(p.data.image)}" alt="${esc(p.data.name)}">`:icon('products')}</div><div class="product-body"><h3>${esc(p.data.name)}</h3><span class="sub">${esc(p.product_number??'—')} · ${esc((p.data.categories||[]).join('، '))}</span><div class="row"><strong>${money(p.data.baseCost)}</strong>${badge(p.active?'مفعّل':'مخفي')}</div><p class="muted">المخزون: ${p.stock}</p><div class="actions">${button('تعديل المنتج','product',p.id)}${button('حذف المنتج','product-delete',p.id,'danger')}</div></div></article>`).join('')||empty('أضف منتجاتك','المنتجات والأسعار والمخزون تُحفظ في التطبيق بعد الإضافة.')}</div>`}
function safeUrl(v){try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)}catch{return false}}
function categories(){return `<div class="grid"><section class="panel"><div class="panelhead"><h2>الأقسام</h2>${button('+ قسم','category-new','','primary')}</div>${table(['القسم','الترتيب','الظهور',''],rows('x_categories').toSorted((a,b)=>a.sort_order-b.sort_order).map(r=>tr([esc(r.name),r.sort_order,badge(r.active?'مفعّل':'مخفي'),button('تعديل','category',r.id)])))}</section><section class="panel"><div class="panelhead"><h2>البنرات</h2>${button('+ بنر','banner-new','','primary')}</div>${table(['الصورة','الترتيب','الظهور',''],rows('x_banners').toSorted((a,b)=>a.sort_order-b.sort_order).map(r=>tr([safeUrl(r.asset)?`<img src="${esc(r.asset)}" alt="بنر" class="banner-thumb">`:esc(r.asset),r.sort_order,badge(r.active?'مفعّل':'مخفي'),`<div class="actions">${button('تعديل','banner',r.id)}${button('حذف','banner-delete',r.id,'danger')}</div>`])))}</section></div><div class="notice">إخفاء القسم يغيّر قائمة الأقسام. عدّل أقسام المنتجات كذلك إذا تريد نقل منتجات القسم.</div>`}
function merchants(){const selected=tab||'merchants';return `<div class="chips">${[['merchants','التجار'],['requests','تعديل البيانات'],['recovery','استرجاع الحساب']].map(([v,l])=>`<button data-tab="${v}" class="${selected===v?'active':''}">${l}</button>`).join('')}</div>${toolbar('ابحث بالاسم أو رقم الهاتف')}<section class="panel">${selected==='requests'?table(['التاجر','التاريخ','الحالة',''],rows('x_profile_requests').filter(matches).map(r=>tr([esc(merchantName(r.merchant_id)),date(r.created_at),badge(r.status==='pending'?'قيد المراجعة':r.status),button('مراجعة','profile-request',r.id)]))):selected==='recovery'?table(['الرقم','الطلب','الحالة',''],rows('x_recovery_requests').filter(matches).map(r=>tr([`<span class="code">${esc(r.phone)}</span>`,esc(r.details.slice(0,70)),badge(r.status),button('مراجعة','recovery',r.id)]))):table(['التاجر','رقم الهاتف','الطلبات','الحالة',''],rows('x_profiles').filter(matches).map(r=>tr([`<strong>${esc(r.data?.name)}</strong><span class="sub">${esc(r.data?.pageName)}</span>`,`<span dir="ltr">${esc(r.phone)}</span>`,rows('x_orders').filter(o=>o.merchant_id===r.user_id).length,badge(r.blocked?'محظور':'نشط'),button('الملف','merchant',r.user_id)])))}</section>`}
function finance(){const ledger=rows('x_wallet_entries'),pending=rows('x_withdrawals').filter(r=>r.status==='قيد الانتظار'),list=rows('x_withdrawals').filter(matches).filter(r=>!filter||r.status===filter).toSorted(newest);return `<div class="metrics">${metric('إجمالي أرصدة التجار',money(ledger.reduce((n,r)=>n+r.amount,0)),'wallet')}${metric('محجوز لسحوبات معلّقة',money(pending.reduce((n,r)=>n+r.amount,0)),'wallet')}${metric('المتاح للسحب',money(ledger.reduce((n,r)=>n+r.amount,0)-pending.reduce((n,r)=>n+r.amount,0)),'wallet')}${metric('تم تسديده',money(rows('x_withdrawals').filter(r=>r.status==='تم التسديد').reduce((n,r)=>n+r.amount,0)),'wallet')}</div>${toolbar('ابحث بالتاجر أو رقم السحب',`<select id="filter" aria-label="حالة السحب"><option value="">كل السحوبات</option>${['قيد الانتظار','تم التسديد','مرفوض'].map(s=>`<option ${filter===s?'selected':''}>${s}</option>`).join('')}</select>`)}<section class="panel"><h2>طلبات السحب</h2>${table(['التاجر','المبلغ','الطريقة / الرقم','الحالة',''],list.map(r=>tr([esc(merchantName(r.merchant_id)),`<strong>${money(r.amount)}</strong>`,`${esc(r.method)}<span class="sub" dir="ltr">${esc(r.number)}</span>`,badge(r.status),button('مراجعة','withdrawal',r.id)])))}</section><section class="panel"><h2>أرصدة التجار</h2>${table(['التاجر','الرصيد','محجوز','المتاح'],rows('x_profiles').map(r=>{let b=ledger.filter(l=>l.merchant_id===r.user_id).reduce((n,l)=>n+l.amount,0),held=pending.filter(w=>w.merchant_id===r.user_id).reduce((n,w)=>n+w.amount,0);return tr([esc(r.data.name),money(b),money(held),money(b-held)])}))}</section>`}
function support(){return `${toolbar('ابحث بالتاجر أو رقم الطلب',`<select id="filter" aria-label="حالة المحادثة"><option value="">كل المحادثات</option><option value="open" ${filter==='open'?'selected':''}>مفتوحة</option><option value="closed" ${filter==='closed'?'selected':''}>مغلقة</option></select>`)}<section class="panel">${table(['التاجر','المحادثة','الطلب','الحالة',''],rows('x_tickets').filter(matches).filter(r=>!filter||r.status===filter).toSorted(newest).map(r=>tr([esc(merchantName(r.merchant_id)),esc(r.type),r.order_id?`<span class="code">${esc(r.order_id.slice(0,12))}</span>`:'—',badge(r.status==='open'?'مفتوحة':'مغلقة'),button('فتح الدردشة','ticket',r.id)])))}</section>`}
function exchange(){return `<section class="panel"><h2>طلبات الاستبدال</h2>${table(['التاجر','الطلب','السبب','الحالة',''],rows('x_exchange_requests').map(r=>tr([esc(merchantName(r.merchant_id)),esc(r.order_id.slice(0,12)),esc(r.data?.reason||r.data?.notes||''),badge(r.status),button('مراجعة','exchange',r.id)])))}</section><section class="panel"><h2>الإحالات</h2><p class="muted">مكافأة 1,000 دينار بعد إكمال التاجر المُحال 3 طلبات ناجحة.</p>${table(['صاحب الإحالة','التاجر المُحال','طلبات ناجحة','المكافأة'],rows('x_referrals').map(r=>tr([esc(merchantName(r.referrer_id)),esc(merchantName(r.referred_id)),rows('x_orders').filter(o=>o.merchant_id===r.referred_id&&o.status==='تم التوصيل').length,badge(r.rewarded?'تمت إضافة المكافأة':'بانتظار التأهل')])))}</section>`}
function notifications(){return `<section class="panel"><h2>إرسال إشعار للتجار</h2><form id="notification-form"><div class="field"><label for="recipient">المستلم</label><select id="recipient" name="user"><option value="all">كل التجار النشطين</option>${rows('x_profiles').map(r=>`<option value="${esc(r.user_id)}">${esc(r.data.name)} · ${esc(r.phone)}</option>`).join('')}</select></div>${area('text','نص الإشعار')}<button class="primary" type="submit">إرسال الإشعار</button></form></section><div class="notice">الإشعار يُحفظ في حساب التاجر ويظهر داخل التطبيق. إشعارات الهاتف بالخلفية تحتاج تفعيل خدمة إشعارات منفصلة.</div><section class="panel"><h2>آخر الإشعارات</h2>${table(['التاجر','الإشعار','التاريخ','القراءة'],rows('x_notifications').toSorted(newest).slice(0,100).map(r=>tr([esc(merchantName(r.merchant_id)),esc(r.text),date(r.created_at),r.is_read?'مقروء':'غير مقروء'])))}</section>`}
function settings(){let d=rows('x_settings')[0]?.data||{};return `<section class="panel"><h2>إعدادات التطبيق</h2><form id="settings-form"><div class="formgrid">${field('deliveryCost','رسوم التوصيل بالدينار',d.deliveryCost??5000,'number','min="0" required')}${field('freeDeliveryMinimumProfit','الحد الأدنى للربح للتوصيل المجاني',d.freeDeliveryMinimumProfit??7000,'number','min="0" required')}${field('landingBaseUrl','رابط موقع صفحات الحجز',d.landingBaseUrl||'','url')}${check('bannerEnabled','إظهار البنرات داخل التطبيق',d.bannerEnabled!==false)}</div><button class="primary" type="submit">حفظ الإعدادات</button></form></section><section class="panel"><h2>الوصول للإدارة</h2><div class="notice">صلاحية الإدارة تُفحص بالسيرفر لكل عملية. تسجيل دخول تاجر وحده لا يسمح بإدارة التطبيق.</div><p>إضافة حسابات الإدارة تتم من مالك مشروع سوبا بيس. حسابات الموظفين داخل تطبيق التاجر تخص نشاطه التجاري فقط.</p></section><section class="panel"><h2>صفحات حجز التجار</h2>${table(['التاجر','المنتج','سعر البيع','الحالة',''],rows('x_landing_pages').map(r=>tr([esc(merchantName(r.merchant_id)),esc(rows('x_products').find(p=>p.id===r.product_id)?.data?.name||r.product_id),money(r.sale),badge(r.active?'مفعّلة':'مخفية'),d.landingBaseUrl?button('نسخ الرابط','landing-link',r.id):'بانتظار نشر موقع الحجز'])))}</section>`}
function audit(){return `${toolbar('ابحث بالعملية أو رقم السجل')}<section class="panel">${table(['التاريخ','العملية','الحساب','العنصر',''],rows('x_audit').filter(matches).toSorted((a,b)=>b.id-a.id).map(r=>tr([date(r.created_at),esc(r.action),`<span class="code">${esc(merchantName(r.actor_id))}</span>`,`<span class="code">${esc(r.entity_id?.slice(0,20))}</span>`,button('التفاصيل','audit',r.id)])))}</section>`}
function wirePage(){const input=$('#search');if(input)input.oninput=e=>{search=e.target.value;const pos=e.target.selectionStart;page();$('#search').focus();$('#search').setSelectionRange(pos,pos)};const f=$('#filter');if(f)f.onchange=e=>{filter=e.target.value;page()};if($('#settings-form'))$('#settings-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),old=rows('x_settings')[0]?.data||{},delivery=Number(f.get('deliveryCost')),min=Number(f.get('freeDeliveryMinimumProfit'));confirmation('حفظ إعدادات التطبيق','تطبّق الرسوم الجديدة على الطلبات الجديدة فقط، والطلبات السابقة تحتفظ بمبالغها.',async()=>{if(!Number.isSafeInteger(delivery)||delivery<0||!Number.isSafeInteger(min)||min<0)throw new Error('راجع المبالغ');await result(sb.from('x_settings').upsert({id:true,data:{...old,deliveryCost:delivery,freeDeliveryMinimumProfit:min,landingBaseUrl:f.get('landingBaseUrl')||null,bannerEnabled:f.has('bannerEnabled')}}))})};if($('#notification-form'))$('#notification-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),txt=String(f.get('text')).trim();if(!txt)return toast('اكتب نص الإشعار');confirmation('إرسال الإشعار',`إرسال «${txt}» إلى ${f.get('user')==='all'?'كل التجار النشطين':merchantName(f.get('user'))}؟`,()=>rpc('x_admin_notify',{p_user:f.get('user')==='all'?null:f.get('user'),p_text:txt}))}}
async function optimizeImage(file){
 if(!['image/jpeg','image/png'].includes(file.type)||file.size<100000)return file;
 const bitmap=await createImageBitmap(file);
 try{
  const scale=Math.min(1,1200/Math.max(bitmap.width,bitmap.height));
  const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);
  const c=canvas.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,canvas.width,canvas.height);c.drawImage(bitmap,0,0,canvas.width,canvas.height);
  const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.76));
  return blob&&blob.size<file.size?new File([blob],file.name.replace(/\.[^.]+$/, '')+'.jpg',{type:'image/jpeg'}):file;
 }finally{bitmap.close()}
}
async function upload(file,privateFile=false){if(!file?.size)return null;if(!privateFile)file=await optimizeImage(file);if(file.size>2*1024*1024)throw new Error('حجم الملف لازم أقل من 2 ميغابايت');if(!['image/jpeg','image/png',...(privateFile?['application/pdf']:[])].includes(file.type))throw new Error('استخدم JPG أو PNG'+(privateFile?' أو PDF':''));const ext=file.type==='image/png'?'png':file.type==='application/pdf'?'pdf':'jpg',path=user.id+'/'+uuid()+'.'+ext,bucket=privateFile?'x-space-private':'x-space-media';await result(sb.storage.from(bucket).upload(path,file,{contentType:file.type,cacheControl:privateFile?'3600':'31536000',upsert:false}));return privateFile?path:sb.storage.from(bucket).getPublicUrl(path).data.publicUrl}
async function signed(path){const r=await result(sb.storage.from('x-space-private').createSignedUrl(path,60));return r.signedUrl}
function detail(label,value){return `<div><span>${label}</span><strong>${esc(value??'—')}</strong></div>`}
function orderDetail(id){const o=rows('x_orders').find(r=>r.id===id);if(!o)return;const c=o.payload.customer||{},items=o.payload.items||[];modal('تفاصيل الطلب',`<div class="actions"><span class="code">${esc(id)}</span>${button('نسخ رقم الطلب','copy-order',id)}${badge(o.status)}</div><div class="detailgrid" style="margin-top:20px">${detail('الزبون',c.name)}${detail('رقم الهاتف',c.phone)}${detail('التاجر',merchantName(o.merchant_id))}${detail('المحافظة',c.province)}${detail('المنطقة والعنوان',c.address||c.area)}${detail('الملاحظات',c.note)}${detail('ملاحظات الشركة',c.companyNote)}${detail('تاريخ الطلب',date(o.created_at))}</div><div class="actions" style="margin-top:15px">${/^07\d{9}$/.test(c.phone)?`<a class="badge blue" href="tel:${esc(c.phone)}">اتصال بالزبون</a><a class="badge green" href="https://wa.me/964${esc(c.phone.slice(1))}" target="_blank" rel="noopener">واتساب</a>`:''}</div><div class="price-banner"><strong>المبلغ المتفق: ${money((o.payload.sales||0)+(o.payload.delivery||0))}</strong><span>ربح التاجر: ${money(o.payload.profit)}</span></div>${table(['المنتج','اللون / القياس','الكمية','سعر البيع','سعر الجملة'],items.map(i=>tr([esc(i.productName||i.name||rows('x_products').find(p=>p.id===(i.productId||i.id))?.data?.name||i.productId),esc([i.color,i.size].filter(Boolean).join(' / ')),esc(i.quantity),money(i.sale),money(i.unitCost||i.cost)])))}${!['تم التوصيل','مرفوض'].includes(o.status)?`<div class="field" style="margin-top:20px"><label for="new-status">تحديث الحالة</label><select id="new-status">${statuses.map(s=>`<option ${o.status===s?'selected':''}>${s}</option>`).join('')}</select></div>${button('حفظ الحالة','order-status',id,'primary')}`:'<div class="notice">حالة نهائية. لا يمكن تغييرها من هذه الصفحة.</div>'}${o.cancellation_requested?`<div class="notice">التاجر طلب إلغاء هذا الطلب.</div><div class="actions">${button('قبول الإلغاء','cancel-accept',id,'danger')}${button('رفض الإلغاء','cancel-reject',id)}</div>`:''}<div class="footer">${rows('x_tickets').find(t=>t.order_id===id)?button('دعم الطلب','ticket',rows('x_tickets').find(t=>t.order_id===id).id):''}</div>`)}
